from pathlib import Path
from collections import Counter
import json,csv,re
R=Path(__file__).resolve().parents[1];out=R/'task3-runs/2026-11-11-local'
master=json.loads((R/'checklist_data.json').read_text(encoding='utf-8'))
runs={}
for engine in ['chrome','firefox']:
 folder=R/(R/f'task3-runs/LATEST-{engine}.txt').read_text().strip()
 runs[engine]=json.loads((folder/'execution.json').read_text(encoding='utf-8'))
 runs[engine]['path']=str(folder.relative_to(R)).replace('\\','/')
