for i in master['items']:
 if i['id'] in native:
  android[i['id']]={'status':i['status'],'notes':i['notes'],'method':'Sinh viên xác nhận thủ công' if i['id'] in ('CHK-IA02-11','CHK-IA03-08') else 'Đối chiếu ảnh thiết bị thật / phép đo màu source','evidence':[f'task3-runs/2026-11-11-local/android/android_{n}_watermarked.png' for n in mapping[i['id']]]}
