android['CHK-IA03-10']={'status':'Passed','notes':'Sinh viên đã xác nhận mục này Passed trong nhóm 5 mục trước đây Not Run. Không ghi là Playwright đã duyệt link native.','method':'Sinh viên xác nhận thủ công','evidence':['task1-runs/mobile-manual/student-confirmations.json']}
rows=[]
for item in master['items']:
 row={'id':item['id'],'aspect':item['aspect'],'criterion':item['description'],'platforms':{}}
 for engine in ['chrome','firefox']:
  v=next(v for v in runs[engine]['results'] if v['id']==item['id'])
  row['platforms'][engine]={'status':v['status'],'notes':v['notes'],'method':'Playwright + API local thật','evidence':v['evidence'],'log':runs[engine]['path']+'/execution.json'}
 row['platforms']['android']=android.get(item['id'],{'status':'Not Applicable','notes':'Tiêu chí này gắn với màn hình/component web hoặc Admin trong phạm vi checklist gốc; native được chọn là Home/Register và header/navigation chung. Không suy từ N/A thành Pass.','method':'Phân định phạm vi','evidence':[]})
 rows.append(row)
counts={p:dict(Counter(row['platforms'][p]['status'] for row in rows)) for p in ['chrome','firefox','android']}
applied=sum(c.get('Passed',0)+c.get('Failed',0) for c in counts.values())
assert len(rows)==48 and applied==91
assert counts['chrome']=={'Failed':19,'Passed':21,'Not Applicable':8} or sum(counts['chrome'].values())==48
assert all((R/e).exists() for row in rows for p in row['platforms'].values() for e in p.get('evidence',[]))
